function CancelBookingDialog({
  bookingId,
  onClose,
  onConfirmed,
}: {
  bookingId: number | null;
  onClose: () => void;
  onConfirmed: (id: number) => Promise<void>;
}) {
  const t = useT();
  const open = bookingId !== null;
  const { data: preview, isLoading } = useGetRefundPreview(bookingId ?? 0, {
    query: { queryKey: getGetRefundPreviewQueryKey(bookingId ?? 0), enabled: open },
  });
  const [submitting, setSubmitting] = useState(false);

  const hours = preview?.hoursBeforeStart ?? 0;
  const refundEur = preview?.refundAmount ?? 0;
  const isFreeSlot = (preview?.totalPrice ?? 0) <= 0;
  const isLate = !preview?.refundable;
  const tierKey = (preview?.refundPercent ?? 0) >= 80
    ? "bookings.cancel.tier80"
    : (preview?.refundPercent ?? 0) >= 50
      ? "bookings.cancel.tier50"
      : "bookings.cancel.tier0";

  const handleConfirm = async () => {
    if (!bookingId) return;
    setSubmitting(true);
    try {
      await onConfirmed(bookingId);
      onClose();
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{t("bookings.cancel.title")}</DialogTitle>
          <DialogDescription>
            {isLoading || !preview
              ? t("bookings.cancel.loading")
              : preview.canCancel
              ? isFreeSlot
                ? t("bookings.cancel.freeSlot").replace("{hours}", hours.toFixed(1))
                : t(tierKey)
              : preview.reason ?? t("bookings.cancel.notAllowed")}
          </DialogDescription>
        </DialogHeader>

        {preview && preview.canCancel && !isFreeSlot && (
          <div className="rounded-lg border bg-muted/40 p-3 text-sm space-y-1.5">
            <div className="flex justify-between">
              <span className="text-muted-foreground">{t("bookings.cancel.totalPaid")}</span>
              <span className="font-medium">€{preview.totalPrice.toFixed(2)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted-foreground">{t("bookings.cancel.refundPercent")}</span>
              <span className="font-medium">{preview.refundPercent}%</span>
            </div>
            <div className="flex justify-between border-t pt-1.5 mt-1.5">
              <span className="font-semibold">{t("bookings.cancel.refundAmount")}</span>
              <span className={`font-bold ${isLate ? "text-destructive" : "text-green-600 dark:text-green-400"}`}>
                €{refundEur.toFixed(2)}
              </span>
            </div>
          </div>
        )}

        <p className="text-xs text-muted-foreground">{t("bookings.cancel.policyShort")}</p>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={onClose} disabled={submitting}>
            {t("bookings.cancel.keep")}
          </Button>
          <Button
            variant="destructive"
            onClick={handleConfirm}
            disabled={submitting || !preview?.canCancel}
          >
            {submitting ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : null}
            {t("bookings.cancel.confirm")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function getStatusBadge(status: string, t: ReturnType<typeof useT>, refundAmount?: number, isSplit?: boolean) {
  switch (status) {
    case "confirmed":
      return <Badge className="bg-green-500 hover:bg-green-600 text-white text-xs"><CheckCircle2 className="w-3 h-3 mr-1" />{t("bookings.status.confirmed")}</Badge>;
    case "pending":
      if (isSplit) {
        return <Badge variant="secondary" className="bg-orange-500/20 text-orange-700 dark:text-orange-400 text-xs"><Clock className="w-3 h-3 mr-1" />Laukiama mokėjimo</Badge>;
      }
      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400 text-xs"><Clock className="w-3 h-3 mr-1" />{t("bookings.status.pending")}</Badge>;
    case "awaiting_players":
      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400 text-xs"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
    case "cancelled": {
      const r = Number(refundAmount ?? 0);
      const label = r > 0
        ? `${t("bookings.status.cancelled")} · ${t("bookings.cancel.refunded")} €${r.toFixed(2)}`
        : `${t("bookings.status.cancelled")} · ${t("bookings.cancel.noRefund")}`;
      return <Badge variant="destructive" className="text-xs"><XCircle className="w-3 h-3 mr-1" />{label}</Badge>;
    }
    default:
      return <Badge variant="outline" className="text-xs">{status}</Badge>;
  }
}

function useCountdown(targetMs: number | null): string | null {
  const [label, setLabel] = useState<string | null>(null);
  useEffect(() => {
    if (targetMs === null) return;
    const update = () => {
      const diff = targetMs - Date.now();
      if (diff <= 0) { setLabel("Laikas baigėsi"); return; }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      if (h > 0) setLabel(`${h} val. ${m} min.`);
      else if (m > 0) setLabel(`${m} min. ${s} sek.`);
      else setLabel(`${s} sek.`);
    };
    update();
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, [targetMs]);
  return label;
}

function BookingCard({
  booking,
  isUpcoming,
  onRate,
  onReviewCoach,
  onCancel,
  cancelling,
}: {
  booking: BookingItem;
  isUpcoming: boolean;
  onRate: () => void;
  onReviewCoach: () => void;
  onCancel: () => void;
  cancelling: boolean;

  cancelling: boolean;
}) {
  const t = useT();
  const [, setLocation] = useLocation();

  const dateLabel = format(booking.date, "yyyy-MM-dd");
  const dayLabel = format(booking.date, "EEEE", { locale: lt });
  const createdLabel = booking.createdAt
    ? format(new Date(booking.createdAt), "yyyy-MM-dd HH:mm")
    : null;

  // Guarantee deadline = game start − 2 h (only relevant for awaiting_players split bookings)
  const guaranteeDeadlineMs = (booking.isSplit && booking.status === "awaiting_players")
    ? new Date(`${dateLabel}T${booking.startTime}:00`).getTime() - 2 * 60 * 60 * 1000
    : null;
  const countdown = useCountdown(guaranteeDeadlineMs);

  // Defensive override: treat any unresolved booking (pending or awaiting_players)
  // whose game start has already passed as failed — covers both sweeper misses and
  // abandoned host checkouts (pending split with no confirmation).
  const gameStartMs = new Date(`${dateLabel}T${booking.startTime}:00`).getTime();
  const isZombieBooking = (booking.status === "awaiting_players" || booking.status === "pending")
    && Date.now() > gameStartMs;

  return (
    <div
      className={`bg-card border rounded-xl p-4 space-y-3 cursor-pointer hover:border-primary/40 hover:shadow-sm transition-all group${isZombieBooking ? " opacity-60" : ""}`}
      onClick={() => setLocation(`/bookings/${booking.id}`)}
    >
      {/* Top row: headline + status. Coach lessons get a graduation icon and
          a "Pamoka su X" lead line, with the court name demoted to a small
          subline. Plain court rentals keep the original single-line layout. */}
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          {booking.coach ? (
            <>
              <p className="font-semibold text-sm group-hover:text-primary transition-colors truncate flex items-center gap-1.5">
                <GraduationCap className="w-4 h-4 text-primary shrink-0" />
                Pamoka su {booking.coach.name}
              </p>
              <p className="text-xs text-muted-foreground mt-0.5 truncate">
                {booking.courtName || `Kortas #${booking.courtId}`}
              </p>
            </>
          ) : (
            <p className="font-semibold text-sm group-hover:text-primary transition-colors truncate">
              {booking.courtName || `Kortas #${booking.courtId}`}
            </p>
          )}
        </div>
        <div className="flex items-center gap-1.5 shrink-0">
          {isZombieBooking
            ? <Badge variant="secondary" className="bg-red-500/20 text-red-700 dark:text-red-400 text-xs"><XCircle className="w-3 h-3 mr-1" />Nepavyko</Badge>
            : getStatusBadge(booking.status, t, booking.refundAmount, booking.isSplit)
          }
          <ChevronRight className="w-4 h-4 text-muted-foreground/50" />
        </div>
      </div>

      {/* Date/time + price row */}
      <div className="flex items-center gap-4 text-sm text-muted-foreground">
        <span className="flex items-center gap-1.5">
          <Calendar className="w-3.5 h-3.5" />
          <span className="capitalize">{dayLabel},</span>
          <span>{dateLabel}</span>
        </span>
        <span className="flex items-center gap-1">
          <Clock className="w-3.5 h-3.5" />
          {booking.startTime} – {booking.endTime}
        </span>
      </div>
      {createdLabel && (
        <div className="text-xs text-muted-foreground/70">
          {t("bookings.bookedAt")}: {createdLabel}
        </div>
      )}

      {/* Split badge */}
      {booking.isSplit && (
        <div className={`flex items-start gap-1.5 text-xs rounded-lg px-2.5 py-2 ${
          isZombieBooking
            ? "bg-muted/40 border border-border"
            : "bg-blue-500/10 border border-blue-400/20"
        }`}>
          <Users className={`w-3.5 h-3.5 shrink-0 mt-0.5 ${isZombieBooking ? "text-muted-foreground" : "text-blue-600 dark:text-blue-400"}`} />
          <div className="space-y-0.5 flex-1 min-w-0">
            <div className="flex items-center justify-between gap-2">
              <span className={`font-medium ${isZombieBooking ? "text-muted-foreground" : "text-blue-700 dark:text-blue-400"}`}>Bendras mokėjimas</span>
              {booking.totalSlots != null && (
                <span className={`font-semibold ${
                  isZombieBooking
                    ? "text-muted-foreground"
                    : booking.status === "confirmed" ? "text-green-600 dark:text-green-400" : "text-orange-500 dark:text-orange-400"
                }`}>
                  {booking.status === "confirmed"
                    ? `${booking.totalSlots}/${booking.totalSlots} ✓`
                    : `${booking.paidSlots ?? 0}/${booking.totalSlots} apmokėta`}
                </span>
              )}
            </div>
            <div className={isZombieBooking ? "text-muted-foreground/70" : "text-blue-600/80 dark:text-blue-400/70"}>
              Jūsų dalis:{" "}
              <span className="font-semibold">
                {booking.pricePerSlot != null ? `€${Number(booking.pricePerSlot).toFixed(2)}` : "—"}
              </span>
              {" · "}Viso:{" "}
              <span className="font-semibold">€{Number(booking.totalPrice).toFixed(2)}</span>
            </div>
            {isZombieBooking ? (
              <div className="flex items-center gap-1 text-red-600 dark:text-red-400 font-medium pt-0.5">
                <XCircle className="w-3 h-3 shrink-0" />
                Mačas neįvyko
              </div>
            ) : countdown ? (
              <div className="flex items-center gap-1 text-amber-700 dark:text-amber-400 font-medium pt-0.5">
                <Clock className="w-3 h-3 shrink-0" />
                Liko: {countdown}
              </div>
            ) : null}
          </div>
        </div>
      )}

      {/* Price + actions */}
      <div className="flex items-center justify-between pt-1 border-t border-border/50">
        <div className="flex flex-col">
          <span className="text-sm font-semibold">
            {booking.isSplit && booking.pricePerSlot != null
              ? (booking.pricePerSlot > 0 ? `€${Number(booking.pricePerSlot).toFixed(2)}` : "Nemokama")
              : (booking.totalPrice > 0 ? `€${Number(booking.totalPrice).toFixed(2)}` : "Nemokama")}
          </span>
          {booking.isSplit && booking.pricePerSlot != null && (
            <span className="text-[10px] text-muted-foreground">iš €{Number(booking.totalPrice).toFixed(2)} viso</span>
          )}
        </div>
        <div className="flex gap-2" onClick={e => e.stopPropagation()}>
          {!isUpcoming && booking.status === "confirmed" && booking.coach ? (
            // Coach lessons: a single button that switches between "submit"
            // and "edit" modes depending on whether the booker has already
            // left a review (coachReview != null). Unique(bookingId) on the
            // server is the last-line dedupe guard.
            booking.coachReview ? (
              <Button
                variant="ghost"
                size="sm"
                className="text-muted-foreground hover:text-foreground gap-1 h-8 text-xs"
                onClick={onReviewCoach}
              >
                <Star className="h-3 w-3" />
                Redaguoti atsiliepimą
              </Button>
            ) : (
              <Button
                variant="outline"
                size="sm"
                className="text-amber-600 hover:text-amber-700 border-amber-200 hover:bg-amber-50 dark:border-amber-900 dark:hover:bg-amber-900/20 gap-1 h-8 text-xs"
                onClick={onReviewCoach}
              >
                <Star className="h-3 w-3" />
                Palikti atsiliepimą
              </Button>
            )
          ) : (
            !isUpcoming && booking.status === "confirmed" && (
              // Non-coach booking: court review path. Same edit/create switch
              // as the coach button. Once submitted, the courtReview field is
              // populated and the button flips to ghost-style "Redaguoti".
              booking.courtReview ? (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-muted-foreground hover:text-foreground gap-1 h-8 text-xs"
                  onClick={onRate}
                >
                  <Star className="h-3 w-3" />
                  Redaguoti atsiliepimą
                </Button>
              ) : (
                <Button
                  variant="outline"
                  size="sm"
                  className="text-yellow-600 hover:text-yellow-700 border-yellow-200 hover:bg-yellow-50 dark:border-yellow-900 dark:hover:bg-yellow-900/20 gap-1 h-8 text-xs"
                  onClick={onRate}
                >
                  <Star className="h-3 w-3" />
                  {t("bookings.rate")}
                </Button>
              )
            )
          )}
          {isUpcoming && (booking.status === "confirmed" || booking.status === "awaiting_players") && (
            <Button
              variant="ghost"
              size="sm"
              className="text-destructive hover:text-destructive hover:bg-destructive/10 h-8 text-xs"
              onClick={onCancel}
              disabled={cancelling}
            >
              {t("bookings.cancel")}
            </Button>

