function RecurringCancelDialog({
  target,
  onClose,
  onCancelOne,
  onCancelAll,
}: {
  target: { bookingId: number; groupId: string } | null;
  onClose: () => void;
  onCancelOne: (id: number) => Promise<void>;
  onCancelAll: (groupId: string) => Promise<void>;
}) {
  const [submitting, setSubmitting] = useState(false);

  const handleOne = async () => {
    if (!target) return;
    setSubmitting(true);
    try { await onCancelOne(target.bookingId); onClose(); } finally { setSubmitting(false); }
  };

  const handleAll = async () => {
    if (!target) return;
    setSubmitting(true);
    try { await onCancelAll(target.groupId); onClose(); } finally { setSubmitting(false); }
  };

  return (
    <Dialog open={!!target} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>Atšaukti kartojamą rezervaciją</DialogTitle>
          <DialogDescription>
            Ši rezervacija yra kartojamos serijos dalis. Ką norėtumėte atšaukti?
          </DialogDescription>
        </DialogHeader>
        <DialogFooter className="flex-col gap-2 sm:flex-col">
          <Button variant="outline" onClick={handleOne} disabled={submitting} className="w-full justify-start">
            {submitting ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : <RotateCcw className="w-4 h-4 mr-1.5 text-muted-foreground" />}
            Atšaukti tik šią
          </Button>
          <Button variant="destructive" onClick={handleAll} disabled={submitting} className="w-full justify-start">
            {submitting ? <Loader2 className="w-4 h-4 mr-1.5 animate-spin" /> : <XCircle className="w-4 h-4 mr-1.5" />}
            Atšaukti visas likusias serijoje
          </Button>
          <Button variant="ghost" onClick={onClose} disabled={submitting} className="w-full">
            Palikti
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

