366	router.post("/payments/confirm", async (req, res): Promise<void> => {
367	  const parsed = ConfirmPaymentBody.safeParse(req.body);
368	  if (!parsed.success) {
369	    res.status(400).json({ error: parsed.error.message });
370	    return;
371	  }
372	
373	  const { sessionId } = parsed.data;
374	
375	  const rows = await db
376	    .select({
377	      booking: bookingsTable,
378	      courtName: courtsTable.name,
379	      courtId: courtsTable.id,
380	      courtAddress: facilitiesTable.address,
381	      courtCity: facilitiesTable.city,
382	      courtPhone: courtsTable.phone,
383	      courtImageUrl: courtsTable.imageUrl,
384	      ownerName: facilitiesTable.name,
385	      ownerEmail: facilitiesTable.email,
386	      facilityId: facilitiesTable.id,
387	      instantBookingEnabled: courtsTable.instantBookingEnabled,
388	    })
389	    .from(bookingsTable)
390	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
391	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
392	    .where(eq(bookingsTable.stripeSessionId, sessionId));
393	
394	  if (!rows[0]) {
395	    res.status(404).json({ error: "Booking not found for session" });
396	    return;
397	  }
398	
399	  // Authorization: for authenticated-user bookings, the caller must be the booker.
400	  // Guest bookings (bookerUserId = null) are authorized by possession of the session ID.
401	  const confirmCallerId = getCurrentUserId(req);
402	  if (rows[0].booking.bookerUserId !== null && confirmCallerId !== rows[0].booking.bookerUserId) {
403	    res.status(403).json({ error: "Forbidden" });
404	    return;
405	  }
406	
407	  let linkGameId: number | null = null;
408	  let stripePaymentIntentId: string | null = null;
409	  // Keep a reference to the Stripe client when configured so we can fire the
410	  // coach transfer below without re-loading it.
411	  let stripeClient: any = null;
412	  if (!sessionId.startsWith("mock_")) {
413	    try {
