  {/* Amenities + Surface specs combined */}
  {(() => {
    const hasAmenities = court.amenities && court.amenities.length > 0;
    const surfaceMap: Record<string, string> = { hard: "Kietas", clay: "Molis", grass: "Žolė", carpet: "Kilimas", artificial_grass: "Dirbtinė žolė", wood: "Medis", rubber: "Guma", concrete: "Betonas" };
    const surfaceLabel = court.surface ? (surfaceMap[court.surface] ?? court.surface) : null;
    const isTennisPadel = ["tennis", "padel", "squash", "badminton"].includes((court as any).sport);
    const hasSpecs = !!(surfaceLabel || (isTennisPadel && ((court as any).surfaceSpeed || (court as any).surfaceBounce)));
    if (!hasAmenities && !hasSpecs) return null;
    let amenityPhotosMap: Record<string, string> = {};
    try { amenityPhotosMap = court.amenityPhotos ? JSON.parse(court.amenityPhotos) : {}; } catch {}
    return (
      <div>
        <h2 className="text-xl font-bold mb-3 flex items-center gap-2 after:flex-1 after:h-px after:bg-border after:ml-3">Patogumai</h2>
        <div className="flex flex-wrap gap-2">
          {court.amenities?.map((amenity, i) => {
            const { label, icon: Icon } = getAmenityMeta(amenity);
            const photoUrl = amenityPhotosMap[amenity];
            return photoUrl ? (
              <button
                key={i}
                type="button"
                onClick={() => setAmenityPopup({ label, photoUrl: resolveCourtImage(photoUrl) ?? "" })}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border bg-muted/30 text-xs font-medium hover:border-primary hover:bg-primary/5 transition-all group"
                title={`Žiūrėti nuotrauką: ${label}`}
              >
                <Icon className="w-3.5 h-3.5 text-primary shrink-0" />
                <span>{label}</span>
                <Camera className="w-3 h-3 text-primary/50 group-hover:text-primary transition-colors shrink-0" />
              </button>
            ) : (
              <div key={i} className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border bg-muted/30 text-xs font-medium">
                <Icon className="w-3.5 h-3.5 text-primary shrink-0" />
                <span>{label}</span>
              </div>
            );
          })}
          {/* Surface specs as pills inline with amenities */}
          <SurfaceSpecs
            sport={(court as any).sport}
            surface={court.surface}
            surfaceSpeed={(court as any).surfaceSpeed}
            surfaceBounce={(court as any).surfaceBounce}
          />
        </div>
      </div>
    );
  })()}

