    <div className="px-4 pt-4 pb-3 space-y-4 flex-1 flex flex-col overflow-y-auto md:min-h-0 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">

    {/* Match Context Card — shown only in link-game / upgrade mode */}
