              {/* Selected far-date chip — only appears when user picked
                  a date outside the 7-day window via the popover. Keeps
                  the selection visible so they always know what's set. */}
              {!isInStrip && (
                <button
                  type="button"
                  data-selected="true"
                  onClick={() => setCalendarOpen(true)}
                  className="shrink-0 min-w-[64px] rounded-xl border border-primary bg-primary/10 text-primary px-2 py-1.5 text-center transition-colors"
