                  title="Keisti datą"
                >
                  <div className="text-[10px] font-semibold uppercase tracking-wide text-primary truncate">
                    {format(date, "EEE", { locale: ltLocale })}
                  </div>
                  <div className="text-sm font-semibold leading-tight mt-0.5">
                    {format(date, "MMM d", { locale: ltLocale })}
                  </div>
                </button>
              )}
              {stripDates.map((d, i) => {
                const isSelected = isSameDay(d, date);
                const topLabel =
                  i === 0
                    ? "Šiandien"
                    : i === 1
                      ? "Rytoj"

                    {slots.map((slot, idx) => {
                      const selectedDate = new Date(date);
                      const now = new Date();
                      const isToday =
                        selectedDate.getFullYear() === now.getFullYear() &&
                        selectedDate.getMonth() === now.getMonth() &&
                        selectedDate.getDate() === now.getDate();
                      if (isToday && slot.startTime <= now.toTimeString().slice(0, 5)) return null;
                      const rangeStart = selectedSlotRange?.rangeStart ?? null;
                      const rangeEnd = selectedSlotRange?.rangeEnd ?? null;
                      const isSelected = rangeStart !== null && rangeEnd !== null
                        ? idx >= rangeStart && idx <= rangeEnd
                        : selectedStart === idx && selectedEnd === null;
                      const isRangeStart = idx === rangeStart;
                      const isRangeEnd = idx === rangeEnd;

                      return (
                        <button
                          key={idx}
                          type="button"
                          disabled={!slot.isAvailable}
                          onClick={() => {
                            vibrateTap();
                            handleSlotClick(idx);
                          }}
                          className={`relative rounded-md border px-1 py-1.5 text-[11px] font-medium transition-all duration-150 focus:outline-none ${
                            !slot.isAvailable
                            ? "bg-muted/20 text-muted-foreground/30 border-transparent cursor-not-allowed"
                            : isSelected
                              ? "bg-primary text-primary-foreground border-primary shadow-lg ring-2 ring-primary/30 scale-[0.98]"
                              : "bg-background text-foreground border-border hover:border-primary/60 hover:bg-primary/5 hover:shadow-md hover:-translate-y-0.5 cursor-pointer"
                          }`}
                        >
                          <div className="text-center leading-tight">
                            <div className={`font-semibold text-xs tabular-nums ${isRangeStart || isRangeEnd ? "text-[13px]" : ""} ${!slot.isAvailable ? "line-through opacity-50" : ""}`}>
                              {slot.startTime}
                            </div>
                            <div className={`mt-0.5 text-[10px] tabular-nums font-medium ${isSelected ? "text-primary-foreground/75" : "text-muted-foreground"}`}>
                              {fmtPrice(slot.price)}€
                            </div>
                          </div>
                          {isSelected && (isRangeStart || isRangeEnd) && (
                            <span className="absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full bg-primary-foreground opacity-60 ring-1 ring-primary" />
                          )}
                        </button>
                      );
                    })}
                  </div>
                ) : (
                  <div className="text-center p-4 bg-muted rounded-xl text-sm text-muted-foreground flex flex-col items-center gap-2">
                    <AlertCircle className="w-8 h-8 opacity-50" />
                    <span>Šiai dienai laisvų laikų nėra.</span>
                    {linkGameId ? (
                      <span className="text-xs">
                        Šis kortas gali būti uždarytas pasirinktą dieną. Pabandykite kita data arba{" "}
                        <button
                          type="button"
                          className="underline hover:text-foreground transition-colors"
                          onClick={() => navigate(`/courts?linkGameId=${linkGameId}&date=${dateStr}`)}
                        >
                          pasirinkite kitą kortą
                        </button>
                        .
                      </span>
                    ) : (
                      <span className="text-xs">Pabandykite pasirinkti kitą datą.</span>
                    )}
                  </div>
