                            const d = new Date(date);
                            d.setDate(d.getDate() + i * 7);
                            const label = d.toLocaleDateString("lt-LT", { month: "short", day: "numeric", weekday: "short" });
                            const status = weekStatuses[i];
                            return (
                              <div key={i} className="flex items-center gap-2 text-xs">
                                {status === null ? (
                                  <span className="w-3 h-3 rounded-full border border-muted-foreground/30 animate-pulse bg-muted-foreground/10 shrink-0" />
