                                  <CheckCircle2 className="w-3 h-3 text-green-500 shrink-0" />
                                ) : (
                                  <AlertCircle className="w-3 h-3 text-destructive shrink-0" />
                                )}
                                <span className={`flex-1 capitalize ${status === false ? "line-through text-muted-foreground/50" : "text-foreground/80"}`}>{label}</span>
                                {status === false && <span className="text-destructive/70 text-[10px]">užimta</span>}
                              </div>
                            );
