                </p>
              ) : null}



              </div>

              {/* Desktop sticky reserve footer — always visible */}
              <div className="hidden md:flex relative z-10 flex-col gap-1.5 border-t border-border bg-card px-4 py-2.5 rounded-b-2xl shrink-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                {selectedSlotRange && (
                  <p className={`text-xs text-center ${(court as any).cancellationPolicy === "strict" ? "text-red-500 dark:text-red-400 font-medium" : "text-muted-foreground"}`}>
                    {(court as any).cancellationPolicy === "strict"
                      ? "Dėmesio: Šios aikštelės rezervacija yra negrąžinama."
                      : "Taikoma standartinė atšaukimo politika (iki 80% grąžinimas)."}
                  </p>
                )}
                <div className="flex items-center gap-3">
                {selectedSlotRange ? (
                  <>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs text-muted-foreground truncate flex items-center gap-1.5">
                        <Clock className="w-3.5 h-3.5 shrink-0" />
                        <span className="truncate"><span className="font-medium text-foreground">{bookingDateLabel}</span> · {selectedSlotRange.startTime} – {selectedSlotRange.endTime} · {selectedSlotRange.durationLabel}</span>
