                          type="button"
                          onClick={() => { setSelectedStart(null); setSelectedEnd(null); setSelectedEquipment(new Map()); }}
                          title="Išvalyti"
                          aria-label="Išvalyti"
                          className="shrink-0 ml-auto p-0.5 rounded text-muted-foreground/70 hover:text-destructive hover:bg-destructive/10 transition-colors"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
