                      <div className="h-11 w-32 rounded-xl bg-muted animate-pulse shrink-0" />
                    ) : isSignedIn ? (
                      <Button
                        onClick={() => splitEnabled ? handleSplitReserve() : recurringEnabled ? handleRecurringBookings() : setSummaryOpen(true)}
                        className="button-primary h-11 px-6 font-semibold gap-2 shrink-0"
                        disabled={isPending || splitPending}
                      >
                        {(isPending || splitPending) ? "…" : linkGameId ? "Užsakyti šiam mačui" : splitEnabled ? "Mokėti dalį" : recurringEnabled ? `${recurringWeeks}× Rezervuoti` : "Rezervuoti"}
                      </Button>
                    ) : (
                      <Button onClick={() => setGuestCheckoutOpen(true)} className="button-primary h-11 px-6 font-semibold gap-2 shrink-0" disabled={isPending}>
