                      </Button>
                    )}
                  </>
                ) : (
              <Button className="button-primary w-full h-10 font-semibold opacity-40 cursor-not-allowed" disabled>
                    Pasirinkite laiką
                  </Button>
                )}
                </div>
              </div>
            </div>
          </div>

        </div>


        {/* Related courts carousel */}
        <RelatedCourtsCarousel currentCourtId={courtId} />

      </div>

      {/* Mobile sticky bottom reserve bar */}
      {selectedSlotRange && (
        <div className="md:hidden fixed bottom-0 left-0 right-0 z-50 bg-background/95 backdrop-blur-md border-t shadow-2xl px-4 py-2 safe-area-bottom">
          <p className={`text-xs text-center mb-1 ${(court as any).cancellationPolicy === "strict" ? "text-red-500 dark:text-red-400 font-medium" : "text-muted-foreground"}`}>
            {(court as any).cancellationPolicy === "strict"
              ? "Dėmesio: Šios aikštelės rezervacija yra negrąžinama."
              : "Taikoma standartinė atšaukimo politika (iki 80% grąžinimas)."}
