input.new_string:
  {waitlistSlot && (
    <WaitlistModal
      open={waitlistOpen}
      onOpenChange={setWaitlistOpen}
      courtId={courtId}
      date={dateStr}
      startTime={waitlistSlot.startTime}
      endTime={waitlistSlot.endTime}
      prefillEmail={displayEmail}
      prefillName={displayName !== "Vartotojas" ? displayName : undefined}
    />
  )}

  {/* Recurring booking confirmation dialog */}
  {selectedSlotRange && (
    <Dialog open={recurringSummaryOpen} onOpenChange={setRecurringSummaryOpen}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <RotateCcw className="w-4 h-4 text-primary" />
            Kartojama rezervacija
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-3 py-1">
          {/* Court + time summary */}
          <div className="rounded-lg bg-muted/50 p-3 text-sm space-y-0.5">
            <p className="font-semibold">{court.name}</p>
            <p className="text-muted-foreground">{selectedSlotRange.startTime} – {selectedSlotRange.endTime} · {selectedSlotRange.durationLabel}</p>
          </div>

          {/* Per-week date list with availability */}
          <div className="space-y-1.5">
            <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wide">Datos</p>
            {Array.from({ length: recurringWeeks }, (_, i) => {
              const d = new Date(date);
              d.setDate(d.getDate() + i * 7);
              const label = d.toLocaleDateString("lt-LT", { weekday: "short", month: "short", day: "numeric" });
              const status = weekStatuses[i];
              return (
                <div key={i} className="flex items-center gap-2 text-sm">
                  {status === null || status === undefined ? (
                    <span className="w-4 h-4 rounded-full border border-muted-foreground/30 animate-pulse bg-muted shrink-0" />
                  ) : status ? (
                    <CheckCircle2 className="w-4 h-4 text-green-500 shrink-0" />
                  ) : (
                    <AlertCircle className="w-4 h-4 text-destructive/60 shrink-0" />
                  )}
                  <span className={`flex-1 capitalize ${status === false ? "line-through text-muted-foreground/50" : ""}`}>{label}</span>
                  {status === false && <span className="text-[11px] text-destructive/70">užimta</span>}
                  {status === true && selectedSlotRange.totalPrice > 0 && (
                    <span className="text-[11px] text-muted-foreground tabular-nums">{selectedSlotRange.totalPrice.toFixed(2)} €</span>
                  )}
                </div>
              );
            })}
          </div>

          {/* Totals block */}
          {(() => {
            const loading = weekStatuses.length !== recurringWeeks || weekStatuses.some(s => s === null);
            const avail = weekStatuses.filter(s => s === true).length;
            const skipped = weekStatuses.filter(s => s === false).length;
            const total = avail * selectedSlotRange.totalPrice;
            return (
              <div className="rounded-lg border bg-primary/5 p-3 space-y-1.5">
                <div className="flex justify-between text-sm">
                  <span className="text-muted-foreground">Laisvos savaitės</span>
                  <span className="font-medium">
                    {loading ? <span className="animate-pulse text-muted-foreground">…</span> : `${avail} iš ${recurringWeeks}`}
                  </span>
                </div>
                {!loading && selectedSlotRange.totalPrice > 0 && (
                  <div className="flex justify-between text-base font-bold">
                    <span>Bendra suma</span>
                    <span className="text-primary">{total.toFixed(2)} €</span>
                  </div>
                )}
                {!loading && skipped > 0 && (
                  <p className="text-[11px] text-muted-foreground pt-0.5 border-t border-border">
                    {skipped} užimta{skipped === 1 ? "" : "s"} savaitė{skipped === 1 ? "" : "s"} bus praleista.
                  </p>
                )}
              </div>
            );
          })()}
        </div>

        <div className="flex gap-2 pt-1">
          <Button variant="outline" className="flex-1" onClick={() => setRecurringSummaryOpen(false)}>
            Atšaukti
          </Button>
          <Button
            className="flex-1 gap-1.5"
            disabled={isPending || (weekStatuses.length === recurringWeeks && weekStatuses.every(s => s === false))}
            onClick={async () => {
              setRecurringSummaryOpen(false);
              await handleRecurringBookings();
            }}
          >
            {isPending ? <Loader2 className="w-4 h-4 animate-spin" /> : <><RotateCcw className="w-3.5 h-3.5" /> Patvirtinti</>}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )}
</Layout>

